from PIL import Image

def blob(fname, thresh=80, yrange=None, exclude_top=0):
    im = Image.open("/home/robot/captures/"+fname).convert("L")
    w,h = im.size; px = im.load()
    pts=[]
    y0,y1 = yrange if yrange else (0,h)
    for y in range(y0,y1):
        for x in range(w):
            if px[x,y] < thresh:
                pts.append((x,y))
    return pts, w, h

def centroid(pts):
    n=len(pts); return sum(p[0] for p in pts)/n, sum(p[1] for p in pts)/n, n

# The gripper trapezoid occupies top; bore is the small blob below y~380.
for f in ["wrist_006.png","wrist_007.png","wrist_008.png","wrist_009.png","wrist_010.png"]:
    pts,w,h = blob(f, yrange=(385,480))
    if pts:
        cx,cy,n = centroid(pts)
        xs=[p[0] for p in pts]; ys=[p[1] for p in pts]
        print(f, "cx=%.2f cy=%.2f n=%d xr=%d..%d yr=%d..%d"%(cx,cy,n,min(xs),max(xs),min(ys),max(ys)))
    else:
        print(f, "no blob below 385")
# pin image wrist_005: pin should be near center
pts,w,h = blob("wrist_005.png", yrange=(150,480))
