    out=[]
    for y in sorted(rows):
        xs=rows[y]
        if len(xs)<40:
            out.append((y,min(xs),max(xs),len(xs)))
    return out
for f in ["wrist_018.png","wrist_019.png","wrist_020.png"]:
    print(f, blobs(f)[:40])
